"""v1258c: each sample also records the active states' vtable RVA and RTTI type (to pin the sword-lock Versus31 state seen in 1258b).
v1258b: starts 2.5 m in front (approach 'face'), lets the guard engage for 2 s, then cycles for ~25 s (1258a: the
first block on an unaware guard became a front choke; 10 s gave too few guard swings to parry).
Derives Test-Counterattack-v1258b.ps1 from Test-Fatality-v1256c.ps1 (#9): the source faces the guard from 1 m and cycles
the native parry follow-up of Drive-ParryCounter-v1208 (hold block 700 ms, attack at once, then neutral) until a sword
finisher plays. The scene record also keeps the combat scenes, so the parry (sword_parry_*) that set it up is visible.
The partner must present the finisher's census-1255 id and both worlds must agree the guard is dead."""
from pathlib import Path
P = Path(__file__).resolve().parent
s = P.joinpath('Test-Fatality-v1256c.ps1').read_bytes().decode('utf-8')
nl = '\r\n' if '\r\n' in s else '\n'
def rep(a, b, count=1):
    global s
    assert s.count(a) == count, (a[:100], s.count(a)); s = s.replace(a, b)
rep("$Take='fatality-v1256c',[string]$Candidate='candidate-npc-combat-v1214f'", "$Take='counterattack-v1258c',[string]$Candidate='candidate-npc-combat-v1214g'")
rep("[ValidateSet('choke','lethal','fatality')][string[]]$Kinds=@('fatality'))", "[ValidateSet('choke','lethal','fatality','counter')][string[]]$Kinds=@('counter'))")
rep("# 1256 (1214d, #11): sword-combat finishers", "# 1258 (1214g, #9): counterattack - block 700 ms then attack at once (Drive-ParryCounter-v1208 cycle) until a finisher plays." + nl +
    "# Generated by make_counterattack_v1258.py from Test-Fatality-v1256c.ps1; combat scenes are recorded alongside." + nl + "# 1256 (1214d, #11): sword-combat finishers")
rep("if($kind-eq'fatality'){& \"$lab/Send-D2Input.ps1\" -Role $source -RightTrigger 255 -DurationMs 200|Out-Null}elseif",
    "if($kind-eq'counter'){& \"$lab/Send-D2Input.ps1\" -Role $source -Button RightShoulder -DurationMs 700|Out-Null;Start-Sleep -Milliseconds 700;& \"$lab/Send-D2Input.ps1\" -Role $source -RightTrigger 255 -DurationMs 150|Out-Null;Start-Sleep -Milliseconds 150;& \"$lab/Send-D2Input.ps1\" -Role $source -DurationMs 100|Out-Null}" +
    "elseif($kind-eq'fatality'){& \"$lab/Send-D2Input.ps1\" -Role $source -RightTrigger 255 -DurationMs 200|Out-Null}elseif")
rep("$attempts-lt$(if($kind-eq'fatality'){18}else{3})", "$attempts-lt$(if($kind-eq'counter'){7}elseif($kind-eq'fatality'){18}else{3})")
rep("-ge$(if($kind-eq'fatality'){450}", "-ge$(if($kind-eq'counter'){500}elseif($kind-eq'fatality'){450}")
rep("if($kind-ne'fatality'){C $source (PlaceCmd $g $approach)", "if($kind-notin'fatality','counter'){C $source (PlaceCmd $g $approach)")
rep("elseif($kind-eq'fatality'){'*/fatalities/*'}", "elseif($kind-in'fatality','counter'){'*/fatalities/*'}")
rep("-match'/player/.*/(choke|assassination|fatalities)/'", "-match'/player/.*/(choke|assassination|fatalities|combat)/'")
rep("operation='Fatality1256'", "operation='Counterattack1258'", 2)
k = s.index("scope='Sword-combat finishers"); e = s.index("'})", k)
s = s[:k] + "scope='Counterattack (#9): parry follow-up cycles against a host-owned guard under the product controller, both source roles: native parry and finisher scenes, partner phase, shared death and victim position; fixture restored after every case.'" + s[e + 1:]
rep("\"PASS_FATALITY $($rows.Count) cases\"", "\"PASS_COUNTERATTACK $($rows.Count) cases\"")
rep("[string[]]$Approaches=@('front')", "[string[]]$Approaches=@('face')")
rep("[ValidateSet('back','left','right','front','drop','slide')]", "[ValidateSet('back','left','right','front','face','drop','slide')]")
rep("'front'{$x+=$fx;$y+=$fy;$look+=180}", "'front'{$x+=$fx;$y+=$fy;$look+=180}'face'{$x+=2.5*$fx;$y+=2.5*$fy;$look+=180}")
rep("if($kind-eq'counter'){& ", "if($kind-eq'counter'){if(!$row.counterStarted){$row.counterStarted=$true;Start-Sleep -Milliseconds 2000};& ")
rep("$attempts-lt$(if($kind-eq'counter'){7}", "$attempts-lt$(if($kind-eq'counter'){22}")
rep("'-t','13'", "'-t','28'")
rep("'--watch-midnight','11000'", "'--watch-midnight','26000'")
rep("while($watch.ElapsedMilliseconds-lt10500){", "while($watch.ElapsedMilliseconds-lt25500){")
rep("active=@($player.active|ForEach-Object {$_.id});", "active=@($player.active|ForEach-Object {$_.id});activeTypes=@($player.active|ForEach-Object {\"$($_.id):$($_.vtableRva):$($_.type)\"});")
P.joinpath('Test-Counterattack-v1258c.ps1').write_bytes(s.encode('utf-8'))
print('ok')
